  const ignoredFaults: SourceFault[] = [];
  for await (const candidate of candidatesFor(openSource, mediaType, ignoredFaults)) {
    const normalised = normaliseCandidate(candidate);
    if (normalised.value) yield normalised.value;
  }
}

