        const participantOutcomes = participantReferences.map(([role, reference]) => {
          const participantOutcome = applyOverride(
            resolveParticipant(
              `${eventPath}.${role}`,
              reference,
              fixtureOutcome,
              squadBySourceRef,
              squadByCanonicalId,
              squadByDisplayName,
              squadByAlias,
