          resolvedReferences: {
            competition: provenance(competitionOutcome),
            fixture: provenance(fixtureOutcome),
            innings: provenance(inningsOutcome),
            participants: Object.fromEntries(
              participantOutcomes.map(([role, value]) => [role, provenance(value)]),
            ),
          },
        });
      }
    }
  }

