             WHERE m.published_at IS NULL
               AND (m.claim_expires_at IS NULL OR m.claim_expires_at < now())
               AND j.batch_id = $2::bigint
             ORDER BY m.created_at, m.outbox_message_id FOR UPDATE SKIP LOCKED LIMIT 1
